ICE.Q.push(
 {"id":"ssc.sphy.ch1.001","topic":"ssc.sphy.ch1","type":"mc","b":0.3,"tags":["মাত্রা"],"stem":"কোন রাশি যুগলের মাত্রা অভিন্ন?","opts":["চাপ এবং পীড়ন","কাজ ও ক্ষমতা","তড়িৎ প্রবাহ ও দীপন তীব্রতা","ত্বরণ ও দ্রুতি"],"ans":0,"why":["চাপ ও পীড়ন দুটিই একক ক্ষেত্রফলে প্রযুক্ত বল, তাই দুটির মাত্রাই ML⁻¹T⁻²।","","",""]},
 {"id":"ssc.sphy.ch1.002","topic":"ssc.sphy.ch1","type":"mc","b":0.3,"tags":["পদার্থবিজ্ঞানের ইতিহাস"],"stem":"কোন বিজ্ঞানীকে আলোকবিজ্ঞানের স্থপতি হিসেবে বিবেচনা করা হয়?","opts":["আল মাসুদি","ইবনে আল হাইয়াম","ওমর খৈয়াম","আল খোয়ারিজমি"],"ans":1,"fixed":true,"why":["","ইবনে আল হাইয়াম আলোর প্রতিসরণ ও দর্শন নিয়ে পরীক্ষাভিত্তিক কাজ করেন, তাই তাঁকে আলোকবিজ্ঞানের স্থপতি বলা হয়।","",""]},
 {"id":"ssc.sphy.ch1.003","topic":"ssc.sphy.ch1","type":"mc","b":0.5,"tags":["ভৌত রাশি"],"stem":"কোনটি লব্ধ রাশি?","opts":["তাপমাত্রা","পদার্থের পরিমাণ","দীপন তীব্রতা","তাপ"],"ans":3,"why":["","","","তাপ এক ধরনের শক্তি, আর শক্তি মৌলিক রাশি থেকে পাওয়া যায়, তাই এটি লব্ধ রাশি; বাকি তিনটি মৌলিক রাশি।"]},
 {"id":"ssc.sphy.ch1.004","topic":"ssc.sphy.ch1","type":"mc","b":0.3,"tags":["পদার্থবিজ্ঞানের ইতিহাস"],"stem":"কে দেখিয়েছিলেন বিশ্বব্রহ্মাণ্ড ধীরে ধীরে প্রসারিত হচ্ছে?","opts":["আইনস্টাইন","হাবল","গ্যালিলিও","নিউটন"],"ans":1,"fixed":true,"why":["","হাবল দেখান গ্যালাক্সিগুলো একে অন্য থেকে দূরে সরে যাচ্ছে, অর্থাৎ বিশ্বব্রহ্মাণ্ড প্রসারিত হচ্ছে।","",""]},
 {"id":"ssc.sphy.ch1.005","topic":"ssc.sphy.ch1","type":"mc","b":0.5,"tags":["পরিমাপ"],"stem":"একটি তারের ব্যাসার্ধ পরিমাপে 1% ত্রুটি হলে প্রস্থচ্ছেদের ক্ষেত্রফল নির্ণয়ে আপেক্ষিক ত্রুটি কত?","opts":["1%","2%","10%","20%"],"ans":1,"fixed":true,"why":["","A = πr², তাই ক্ষেত্রফলের আপেক্ষিক ত্রুটি ব্যাসার্ধের আপেক্ষিক ত্রুটির দ্বিগুণ: 2 × 1% = 2%।","",""]},
 {"id":"ssc.sphy.ch1.006","topic":"ssc.sphy.ch1","type":"mc","b":0.5,"tags":["পরিমাপ"],"stem":"1 এটো মিটার = কত মিটার?","opts":["10⁻⁹","10⁻¹²","10⁻¹⁵","10⁻¹⁸"],"ans":3,"fixed":true,"why":["","","","এটো (atto, a) উপসর্গের মান 10⁻¹⁸, তাই 1 এটো মিটার = 10⁻¹⁸ মিটার।"]},
 {"id":"ssc.sphy.ch1.007","topic":"ssc.sphy.ch1","type":"mc","b":0.5,"tags":["মাত্রা"],"stem":"ক্ষমতার মাত্রা কোনটি?","opts":["ML²T⁻¹","MLT⁻¹","MLT⁻²","ML²T⁻³"],"ans":3,"fixed":true,"why":["","","","ক্ষমতা = কাজ/সময়। কাজের মাত্রা ML²T⁻², সময় T দিয়ে ভাগ করলে ML²T⁻³।"]},
 {"id":"ssc.sphy.ch1.008","topic":"ssc.sphy.ch1","type":"mc","b":0,"tags":["ভৌত রাশি"],"stem":"নিচের কোনটি স্কেলার রাশি?","opts":["চাপ","বল","সরণ","ওজন"],"ans":0,"fixed":true,"why":["চাপের শুধু মান আছে, দিক নেই, তাই এটি স্কেলার; বল, সরণ ও ওজন ভেক্টর রাশি।","","",""]},
 {"id":"ssc.sphy.ch1.009","topic":"ssc.sphy.ch1","type":"mc","b":0.3,"tags":["ভৌত রাশি"],"stem":"নিচের কোনটি মৌলিক রাশি?","opts":["তড়িৎ তীব্রতা","তড়িৎ পরিবাহিতা","তড়িৎ আধান","তড়িৎ প্রবাহ"],"ans":3,"fixed":true,"why":["","","","সাতটি মৌলিক রাশির একটি হলো তড়িৎ প্রবাহ (একক অ্যাম্পিয়ার); তড়িৎ আধানসহ বাকিগুলো এ থেকে পাওয়া লব্ধ রাশি।"]},
 {"id":"ssc.sphy.ch1.010","topic":"ssc.sphy.ch1","type":"mc","b":0.3,"tags":["ভৌত রাশি"],"stem":"একই একক বিশিষ্ট রাশি যুগল নিচের কোনটি?","opts":["বিকৃতি ও পীড়ন","চাপ ও বল","চাপ ও বিকৃতি","চাপ ও পীড়ন"],"ans":3,"fixed":true,"why":["","","","চাপ ও পীড়ন দুটিই বল/ক্ষেত্রফল, তাই দুটির একক N/m² বা প্যাসকেল।"]},
 {"id":"ssc.sphy.ch1.011","topic":"ssc.sphy.ch1","type":"mc","b":0.3,"tags":["মাত্রা"],"stem":"v² = u² + 2as সমীকরণে 2as এর মাত্রা কোনটি?","opts":["L²T⁻²","LT⁻²","LT⁻¹","LT"],"ans":0,"fixed":true,"why":["a-এর মাত্রা LT⁻² ও s-এর মাত্রা L, আর 2 মাত্রাহীন; গুণ করলে 2as-এর মাত্রা L²T⁻²।","","",""]}
);
